#!/usr/bin/env bash
# ==============================================================================
# SentinelEye — PipeGen Production Execution Script
# Generated by CraftifAI PipeGen v0.5.1
# Pipeline: Workplace Safety Sentinel (Stage 5: Run)
# ==============================================================================

set -e

DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"
ROOT_DIR="$(dirname "$DIR")"

echo "================================================================="
echo "🛡️  SentinelEye — Industrial Workplace Safety Sentinel"
echo "CraftifAI PipeGen v0.5.1 Automated Pipeline Runner"
echo "================================================================="

# Check execution mode
MODE=${1:-"simulator"}

echo "[INFO] Target Architecture: $(uname -m)"
echo "[INFO] Working Directory: $ROOT_DIR"
echo "[INFO] Running Mode: $MODE"

# 1. Start local MQTT Broker if mosquitto is present
if command -v mosquitto >/dev/null 2>&1; then
    echo "[INFO] Starting local MQTT broker on port 1883..."
    mosquitto -d -p 1883 || true
else
    echo "[WARN] Mosquitto daemon not found locally. Running with built-in telemetry fallback."
fi

# 2. Check for NVIDIA DeepStream / TensorRT
if command -v deepstream-app >/dev/null 2>&1 && [ "$MODE" = "deepstream" ]; then
    echo "[STAGE 5: RUN] Launching DeepStream pipeline with TensorRT INT8 engine..."
    deepstream-app -c "$DIR/deepstream_app_config.txt"
else
    echo "[STAGE 5: RUN] Launching SentinelEdge AI Perception Engine..."
    cd "$ROOT_DIR"
    python3 src/sentinel_engine.py --mode "$MODE"
fi
